import sys;sys.path.insert(0,'/app/output')
from geometry import *
for cam in ['forward','left','right']:
 dep=np.load('/app/output/initial/depth_'+cam+'.npy').squeeze()
 points=[]
 for v in range(320):
  for u in range(320):
   p=unproject(cam,u,v,float(dep[v,u]))
   if -.15<p[0]<-.05 and .15<p[1]<.28 and .585<p[2]<.66: points.append(p)
 points=np.array(points)
 def residual(c):return np.linalg.norm(points-c[:3],axis=1)-c[3]
 fit=least_squares(residual,[-.1,.22,.602,.025],loss='soft_l1',f_scale=.001)
 print(cam,len(points),fit.x, np.quantile(abs(fit.fun),[0,.5,.9,1]))
 np.save('/app/output/points_'+cam+'.npy',points)
